public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int length = str.length();
    StringBuilder sb = new StringBuilder(length);
    boolean escaped = false;
    for (int i = 0; i < length; i++) {
        char ch = str.charAt(i);
        if (!escaped && ch == '\\') {
            escaped = true;
            continue;
        } else if (escaped && ch == '\\') {
            sb.append('\\');
            escaped = false;
            continue;
        } else if (escaped && ch == 'n') {
            sb.append('\n');
            escaped = false;
            continue;
        } else if (escaped && ch == 'r') {
            sb.append('\r');
            escaped = false;
            continue;
        } else if (escaped && ch == 't') {
            sb.append('\t');
            escaped = false;
            continue;
        } else if (escaped && ch == 'b') {
            sb.append('\b');
            escaped = false;
            continue;
        } else if (escaped && ch == 'f') {
            sb.append('\f');
            escaped = false;
            continue;
        } else if (escaped && ch == '\'') {
            sb.append('\\');
            sb.append('\'');
            escaped = false;
            continue;
        } else if (escaped && ch == '\"') {
            sb.append('\\');
            sb.append('\"');
            escaped = false;
            continue;
        } else if (escaped && ch == '\\') {
            sb.append('\\');
            sb.append('\\');
            escaped = false;
            continue;
        } else if (!escaped) {
            sb.append(ch);
        }
    }
    if (escaped) {
        throw new Exception("Unterminated escape sequence in string: " + str);
    }
    return sb.toString();
}

