        int lowerBound = findMinLowerBound(key, i);
        upperBounds.add(lowerBound);
    }
    return upperBounds;
}

private int findMinLowerBound(K key, int index) {
    int lowerBound = Integer.MAX_VALUE;
    for (int i = 0; i < index; i++) {
        if (keys.get(i).compareTo(key) <= 0) {
            lowerBound = Math.min(lowerBound, i);
        }
    }
    return lowerBound;
}

