    }
    int lastSeparatorIndex = indexOfLastSeparator(filename);
    int extensionIndex = filename.lastIndexOf(".", lastSeparatorIndex);
    int lastUnixSeparatorIndex = filename.lastIndexOf("/", lastSeparatorIndex);
    int lastWindowsSeparatorIndex = filename.lastIndexOf("\\", lastSeparatorIndex);
    if (lastUnixSeparatorIndex > extensionIndex || lastWindowsSeparatorIndex > extensionIndex) {
        return -1;
    }
    return extensionIndex;
}

